-- Candidate proposals are never read by the release exporter or runtime drop pool.
CREATE TABLE game_collection_candidates(game_id TEXT PRIMARY KEY, object_id TEXT NOT NULL REFERENCES collection_objects(object_id), article_id TEXT REFERENCES editorial_articles(article_id), zh_name TEXT NOT NULL, cohort TEXT NOT NULL CHECK(cohort IN('CHINA','WORLD','NATURAL')), category TEXT NOT NULL, basis_kind TEXT NOT NULL CHECK(basis_kind IN('REAL_OBJECT_REFERENCE','FICTIONAL_ARCHETYPE')), payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), content_sha256 TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'CANDIDATE' CHECK(status IN('CANDIDATE','APPROVED','REJECTED')), history_review TEXT NOT NULL DEFAULT 'PENDING', source_review TEXT NOT NULL DEFAULT 'PENDING', numeric_review TEXT NOT NULL DEFAULT 'PENDING', gameplay_review TEXT NOT NULL DEFAULT 'PENDING', reviewer TEXT, review_note TEXT, CHECK(status!='APPROVED' OR (history_review='PASSED' AND source_review='PASSED' AND numeric_review='PASSED' AND gameplay_review='PASSED' AND reviewer IS NOT NULL AND length(review_note)>0)));
CREATE INDEX candidate_cohort ON game_collection_candidates(cohort,status);
